--
DROP TABLE IF EXISTS `v_daftar_bawahan`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_daftar_bawahan`  AS SELECT `r`.`id` AS `relasi_id`, `r`.`id_atasan` AS `id_atasan`, `atasan`.`nama` AS `nama_atasan`, `atasan`.`jabatan` AS `jabatan_atasan`, `r`.`id_karyawan` AS `id_bawahan`, `bawahan`.`nama` AS `nama_bawahan`, `bawahan`.`jabatan` AS `jabatan_bawahan`, `bawahan`.`status` AS `status_bawahan` FROM ((`relasi_atasan` `r` join `karyawan` `atasan` on((`r`.`id_atasan` = `atasan`.`id`))) join `karyawan` `bawahan` on((`r`.`id_karyawan` = `bawahan`.`id`))) WHERE (`bawahan`.`status` = 'aktif') ;

